/* card_buttons_probe - RikkaST complex probe card #2
 * Assertions: [CARD] card_buttons_probe <check> PASS|FAIL <detail>
 * Channel: console.log + window.parent.__rikkaLog
 * Truth sources: runtime.js:1341-1374 (per-iframe predefine), button-shims.js,
 *                util-shims.js:156 (triggerSlash), lorebook-shims.js:257 (getWorldbookNames)
 */
(function () {
  "use strict";

  var SCRIPT_NAME = "card_buttons_probe";
  var SCRIPT_ID = "622d3f2c-d9b7-4328-8955-72a39aaba0ff";
  var EXPECTED_IFRAME = "TH-script--" + SCRIPT_NAME + "--" + SCRIPT_ID;
  var TAG = "[CARD] card_buttons_probe ";
  var PANEL_TEXT = "[CARD] card_buttons_probe panel_send_probe";

  function parentLog(level, text) {
    try { if (window.parent && typeof window.parent.__rikkaLog === "function") window.parent.__rikkaLog(level, text); } catch (e) { /* noop */ }
  }
  function say(level, text) {
    try { console.log(text); } catch (e) { /* noop */ }
    parentLog(level, text);
  }
  function info(text) { say("info", TAG + "INFO " + text); }
  function check(name, ok, detail) { say(ok ? "info" : "error", TAG + name + (ok ? " PASS " : " FAIL ") + String(detail)); }
  function fail(name, err) { check(name, false, "threw: " + String((err && (err.stack || err.message)) || err).slice(0, 300)); }
  function names(list) { return (list || []).map(function (b) { return b && b.name; }).join(","); }
  function has(list, n) { return (list || []).some(function (b) { return b && b.name === n; }); }
  function findBtn(list, n) { var r = null; (list || []).forEach(function (b) { if (b && b.name === n) r = b; }); return r; }
  function bumpRun() {
    try { var p = window.parent; p.__cbtnRuns = (p.__cbtnRuns || 0) + 1; return p.__cbtnRuns; }
    catch (e) { return -1; }
  }

  var REQUIRED = ["getScriptButtons", "replaceScriptButtons", "appendInexistentScriptButtons",
    "updateScriptButtonsWith", "getButtonEvent", "getScriptId", "getScriptName", "getIframeName",
    "triggerSlash", "eventOn", "eventEmit", "getWorldbookNames"];
  var res = {};

  async function runSuite(run) {
    info("suite run=" + run + " iframe=" + String(window.name || "(unnamed)"));

    /* 0) bare-global API presence */
    var missing = REQUIRED.filter(function (k) { return typeof window[k] !== "function"; });
    check("api_presence", missing.length === 0, missing.length ? ("missing=" + missing.join(",")) : ("all " + REQUIRED.length + " bare globals are functions"));

    /* 0b) environment bare globals (task contract: toastr / $ / _ / TavernHelper) */
    var envMissing = [];
    if (typeof window.$ !== "function") envMissing.push("$");
    if (typeof window._ !== "function") envMissing.push("_");
    if (!window.toastr) envMissing.push("toastr");
    if (!window.TavernHelper) envMissing.push("TavernHelper");
    check("env_globals", envMissing.length === 0, envMissing.length ? ("missing=" + envMissing.join(",")) : ("$=fn _=fn toastr=present TavernHelper=present"));
    /* 1) per-iframe identity */
    var idDetail = "";
    try {
      var sid = String(getScriptId()), sname = String(getScriptName()), ifn = String(getIframeName());
      res.identity = (sid === SCRIPT_ID) && (sname === SCRIPT_NAME) && (ifn === EXPECTED_IFRAME);
      idDetail = "id=" + sid + " name=" + sname + " iframe=" + ifn;
    } catch (e) { res.identity = false; idDetail = "threw: " + ((e && e.message) || e); }
    check("identity_boot", res.identity, idDetail);

    /* 2) button register / query / replace / append-dedupe / update */
    try {
      var appended = appendInexistentScriptButtons([{ name: "CB_ALPHA", visible: true }]);
      res.btnAppend = has(appended, "CB_ALPHA");
      check("btn_append", res.btnAppend, "appendInexistentScriptButtons returned=[" + names(appended) + "]");
      var got = getScriptButtons();
      res.btnGet = has(got, "CB_ALPHA");
      check("btn_get", res.btnGet, "getScriptButtons list=[" + names(got) + "]");
      replaceScriptButtons([{ name: "CB_BETA", visible: true }, { name: "CB_GAMMA", visible: false }]);
      var got2 = getScriptButtons();
      var gamma = findBtn(got2, "CB_GAMMA");
      res.btnReplace = (got2.length === 2) && has(got2, "CB_BETA") && !!gamma && gamma.visible === false;
      check("btn_replace", res.btnReplace, "list=[" + names(got2) + "] gamma.visible=" + (gamma ? gamma.visible : "n/a"));
      appendInexistentScriptButtons([{ name: "CB_BETA", visible: true }]);
      var got3 = getScriptButtons();
      res.btnDedupe = (got3.length === 2);
      check("btn_append_dedupe", res.btnDedupe, "after duplicate append len=" + got3.length + " list=[" + names(got3) + "]");
      updateScriptButtonsWith(function (list) { list.push({ name: "CB_DELTA", visible: true }); return list; });
      var got4 = getScriptButtons();
      res.btnUpdate = has(got4, "CB_DELTA");
      check("btn_update", res.btnUpdate, "updateScriptButtonsWith list=[" + names(got4) + "]");
    } catch (e) { fail("btn_register_block", e); }

    /* 3) button event name (stable) */
    var ev = "", ev2 = "";
    try { ev = String(getButtonEvent("CB_CLICK")); ev2 = String(getButtonEvent("CB_CLICK")); } catch (e) { /* below */ }
    check("btn_event_name", !!ev && ev === ev2, "getButtonEvent('CB_CLICK')=" + ev + " stable=" + (ev === ev2));

    /* 4) click loop: host dispatch -> getButtonEvent -> eventOn -> triggerSlash -> result */
    var click = { fired: false, slash: null, slashTh: null, idOk: false, idDetail: "", done: false };
    function emitClickChecks() {
      if (click.done) return;
      click.done = true;
      check("btn_click_loop", click.fired && typeof click.slash === "string" && click.slash.length > 0,
        "fired=" + click.fired + " triggerSlash(/echo)=" + JSON.stringify(click.slash) + " TavernHelper.triggerSlash=" + JSON.stringify(click.slashTh));
      check("btn_identity_in_callback", click.idOk, click.idDetail);
    }
    try {
      appendInexistentScriptButtons([{ name: "CB_CLICK", visible: true }]);
      eventOn(getButtonEvent("CB_CLICK"), async function () {
        click.fired = true;
        try {
          var s2 = String(getScriptId()), n2 = String(getScriptName()), f2 = String(getIframeName());
          click.idOk = (s2 === SCRIPT_ID) && (n2 === SCRIPT_NAME) && (f2 === EXPECTED_IFRAME);
          click.idDetail = "in-callback id=" + s2 + " name=" + n2 + " iframe=" + f2;
        } catch (e) { click.idDetail = "in-callback threw: " + ((e && e.message) || e); }
        try { click.slash = await triggerSlash("/echo CB_CLICK_ECHO_OK"); } catch (e) { click.slash = "THREW:" + e; }
        try { click.slashTh = await TavernHelper.triggerSlash("/echo CB_CLICK_ECHO_OK"); } catch (e) { click.slashTh = "THREW:" + e; }
        emitClickChecks();
      });
    } catch (e) { fail("btn_click_handler", e); }

    setTimeout(function () {
      try {
        var hub = window.parent && window.parent.__rikkaButtonHub;
        if (!hub || typeof hub.fire !== "function") { click.done = true; check("btn_click_loop", false, "missing window.parent.__rikkaButtonHub.fire (host click dispatch)"); check("btn_identity_in_callback", false, "handler not invoked"); return; }
        var fired = hub.fire(SCRIPT_ID, "CB_CLICK");
        info("click dispatch via parent.__rikkaButtonHub.fire (host path TavernRuntimeManager.fireScriptButton) returned=" + fired);
      } catch (e) { click.done = true; fail("btn_click_loop", e); }
    }, 200);
    setTimeout(function () {
      if (click.done) return;
      if (!click.fired) { click.done = true; check("btn_click_loop", false, "handler not invoked within 5000ms (hub.fire->eventEmit->eventOn)"); check("btn_identity_in_callback", false, "handler not invoked"); return; }
      emitClickChecks();
    }, 5000);

    /* 5) panel form send */
    var panelOk = false, panelApi = null, panelRes = null, panelTried = [];
    var cands = [];
    try { if (window.RikkaBridge && typeof window.RikkaBridge.sendUserMessage === "function") cands.push(["self.RikkaBridge.sendUserMessage", function () { return window.RikkaBridge.sendUserMessage(PANEL_TEXT); }, false]); } catch (e) { panelTried.push("probe-self=threw:" + ((e && e.message) || e)); }
    try { if (window.parent && window.parent.RikkaBridge && typeof window.parent.RikkaBridge.sendUserMessage === "function") cands.push(["parent.RikkaBridge.sendUserMessage", function () { return window.parent.RikkaBridge.sendUserMessage(PANEL_TEXT); }, false]); } catch (e) { panelTried.push("probe-parent=threw:" + ((e && e.message) || e)); }
    try { if (window.TavernHelper && typeof window.TavernHelper.sendUserMessage === "function") cands.push(["TavernHelper.sendUserMessage", function () { return window.TavernHelper.sendUserMessage(PANEL_TEXT); }, false]); } catch (e) { /* noop */ }
    try { if (window.TavernHelper && typeof window.TavernHelper.sendMessage === "function") cands.push(["TavernHelper.sendMessage", function () { return window.TavernHelper.sendMessage(PANEL_TEXT); }, false]); } catch (e) { /* noop */ }
    try { var ta = document.getElementById("send_textarea"), sb = document.getElementById("send_but"); if (ta && sb) cands.push(["panel_dom_stub#send_but", function () { ta.value = PANEL_TEXT; sb.click(); return true; }, false]); } catch (e) { /* noop */ }
    cands.push(["triggerSlash:/send (fallback, empty pipe expected)", function () { return triggerSlash("/send " + PANEL_TEXT); }, true]);
    for (var i = 0; i < cands.length; i++) {
      var label = cands[i][0], acceptAny = cands[i][2];
      try {
        var r = cands[i][1]();
        if (r && typeof r.then === "function") r = await r;
        panelTried.push(label + "=" + JSON.stringify(r));
        if (r === true || (typeof r === "string" && r.length > 0) || (acceptAny && r !== undefined)) { panelOk = true; panelApi = label; panelRes = r; break; }
      } catch (e) { panelTried.push(label + "=threw:" + ((e && e.message) || e)); }
    }
    check("panel_send_api", panelOk, panelOk ? ("api=" + panelApi + " result=" + JSON.stringify(panelRes)) : ("no send API accepted; probed=[" + panelTried.join(" | ") + "]"));

    /* 6) worldbook read-only smoke */
    var wbOk = false, wbDetail = "";
    try {
      var wbn = getWorldbookNames();
      wbOk = Array.isArray(wbn);
      wbDetail = "Array.isArray=" + wbOk + " n=" + (wbOk ? wbn.length : "n/a") + " sample=" + JSON.stringify(wbOk ? wbn.slice(0, 3) : wbn);
      wbDetail += " TavernHelper.getWorldbookNames=" + !!(window.TavernHelper && typeof window.TavernHelper.getWorldbookNames === "function");
    } catch (e) { wbDetail = "threw: " + ((e && e.message) || e); }
    check("worldbook_names", wbOk, wbDetail);

    /* 7) iframe rebuild: force reload -> second pass re-asserts buttons + identity */
    if (run < 0) {
      check("rebuild_trigger", false, "cannot reach window.parent to read run counter");
    } else if (run === 1) {
      setTimeout(function () {
        try {
          var p = window.parent;
          if (p.__cbtnRebuildRequested) { check("rebuild_trigger", true, "already requested"); return; }
          if (!p || typeof p.__rikkaEmit !== "function") { check("rebuild_trigger", false, "parent.__rikkaEmit missing; cannot force reload"); return; }
          p.__cbtnRebuildRequested = true;
          p.__rikkaEmit("active_conversation_changed", "{}");
          check("rebuild_trigger", true, "issued parent.__rikkaEmit(active_conversation_changed) -> runtime.js:1031 loadTavernScripts(true) rebuilds TH-script iframes");
        } catch (e) { fail("rebuild_trigger", e); }
      }, 1800);
    } else if (run >= 2) {
      check("rebuild_second_pass", !!(res.identity && res.btnAppend && res.btnGet),
        "run=" + run + " after force rebuild: identity=" + res.identity + " btn_append=" + res.btnAppend + " btn_get=" + res.btnGet + " iframe=" + String(window.name || ""));
    }

    info("suite done run=" + run);
  }

  function boot() {
    var run = bumpRun();
    info("boot run=" + run + " iframe=" + String(window.name || "(unnamed)") + " jq=" + (typeof window.$) + " TH=" + (window.TavernHelper ? "yes" : "no"));
    function go() { setTimeout(function () { runSuite(run).catch(function (e) { fail("suite_crash", e); }); }, 500); }
    try {
      if (typeof window.$ === "function") { window.$(function () { go(); }); }
      else if (document.readyState === "complete" || document.readyState === "interactive") { go(); }
      else { document.addEventListener("DOMContentLoaded", go); }
    } catch (e) { fail("boot", e); }
  }

  boot();
})();
